  \coordinate (A) at (0,5.278);
  \coordinate (B) at (-4.411,0);
  \coordinate (C) at (2.647,0);
  \coordinate (D) at (0,0);
  \coordinate (E) at (-2.198,2.647);
  \coordinate (F) at (-2.198,0);
  \coordinate (G) at (1.331,0);
  \coordinate (H) at (1.331,2.647);

  % Triangle
  \draw (A) -- (B) -- (C) -- cycle;
  % Altitude
  \draw (A) -- (D);
  % Horizontal line through E and H
  \draw (E) -- (H);
  % Verticals
  \draw (E) -- (F);
  \draw (H) -- (G);

  % Labels
  \node[above] at (A) {$A$};
  \node[below left] at (B) {$B$};
  \node[below right] at (C) {$C$};
  \node[below] at (D) {$D$};
  \node[left] at (E) {$E$};
  \node[below] at (F) {$F$};
